CREATE TABLE issue_comments (id BIGINT AUTO_INCREMENT PRIMARY KEY, issue_id BIGINT NOT NULL, author_id BIGINT NOT NULL, body TEXT NOT NULL, edited BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(issue_id) REFERENCES issues(id), FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE issue_attachments (id BIGINT AUTO_INCREMENT PRIMARY KEY, issue_id BIGINT NOT NULL, uploader_id BIGINT NOT NULL, original_name VARCHAR(255) NOT NULL, storage_key VARCHAR(255) NOT NULL UNIQUE, content_type VARCHAR(120) NOT NULL, size_bytes BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(issue_id) REFERENCES issues(id), FOREIGN KEY(uploader_id) REFERENCES users(id));
